g=[[0]*10 for _ in range(10)]
def place(top,h,w,color):
    cells={(top[0]+r,top[1]+c) for r in range(h) for c in range(w)}
    for (r,c) in cells:
        if g[r][c]!=0: g[r][c]=0   # earlier loses overlap
    for (r,c) in cells: g[r][c]=color
    return (top[0]+h-1, top[1]+w-1)
t=place((0,0),4,1,7)   # 7 line 1x4
t=place(t,3,2,8)       # 8 block 3x2
t=place(t,3,1,6)       # 6 line 1x3
t=place(t,2,2,3)       # 3 block 2x2
